const canvas = document.getElementById('canvas');
canvas.innerHTML = S;
const slides = [...canvas.querySelectorAll('.slide')];

/* ---------- mode deck (grand ecran seulement) ---------- */
function deckActive(){
  return matchMedia('(min-width:1180px) and (min-height:640px)').matches;
}

const dots = document.getElementById('dots');
const dotsArr = slides.map((_, i) => {
  const d = document.createElement('div');
  d.className = 'dot';
  d.addEventListener('click', () => go(i));
  dots.appendChild(d);
  return d;
});
const count = document.getElementById('count');
let cur = 0;

function go(n){
  cur = Math.max(0, Math.min(slides.length - 1, n));
  slides.forEach((s, i) => s.classList.toggle('active', i === cur));
  dotsArr.forEach((d, i) => d.dataset.on = i === cur ? '1' : '0');
  count.textContent = (cur + 1) + ' / ' + slides.length;
  try{ localStorage.setItem('mcpdeck', String(cur)); }catch(e){}
}
function fit(){
  if(!deckActive()){ canvas.style.transform = 'none'; return; }
  const s = Math.min(innerWidth / 1920, innerHeight / 1080);
  canvas.style.transform = 'scale(' + s + ')';
}
function syncMode(){
  const on = deckActive();
  document.documentElement.classList.toggle('deck', on);
  if(on){
    let saved = 0;
    try{ saved = +localStorage.getItem('mcpdeck') || 0; }catch(e){}
    go(Number.isFinite(saved) ? saved : 0);
  }
  fit();
}
syncMode();
addEventListener('resize', syncMode);
addEventListener('orientationchange', () => setTimeout(syncMode, 250));

window.addEventListener('keydown', e => {
  if(!deckActive()) return;
  if(['ArrowRight','ArrowDown',' ','PageDown'].includes(e.key)){ e.preventDefault(); go(cur + 1); }
  if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){ e.preventDefault(); go(cur - 1); }
  if(e.key === 'Home'){ e.preventDefault(); go(0); }
  if(e.key === 'End'){ e.preventDefault(); go(slides.length - 1); }
});

/* swipe (deck only) */
let tx = 0, ty = 0;
addEventListener('touchstart', e => { tx = e.changedTouches[0].clientX; ty = e.changedTouches[0].clientY; }, {passive:true});
addEventListener('touchend', e => {
  if(!deckActive()) return;
  const dx = e.changedTouches[0].clientX - tx;
  const dy = e.changedTouches[0].clientY - ty;
  if(Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy)) go(dx < 0 ? cur + 1 : cur - 1);
}, {passive:true});
